//! The embedded ROM hash database: a game's proper name, region and year by CRC, serial or ROM
//! file name.
//!
//! Data origin: Playnite's emulation databases (generated by Playnite from No-Intro / Redump /
//! libretro DATs; Playnite is MIT-licensed, Copyright (c) Josef Nemec), converted by
//! `scripts/gen-romdb.py` into `assets/emulation/romdb.bin` (format documented there). Each
//! database ("Sony - PlayStation 2") is a separate deflate blob, inflated and indexed the first
//! time it is used and then kept for the life of the process.

use std::collections::HashMap;
use std::sync::OnceLock;

static BLOB: &[u8] = include_bytes!("../../assets/emulation/romdb.bin");

/// One database entry.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct DatEntry {
    /// No-Intro / Redump name ("Some Game (USA)").
    pub name: String,
    pub region: Option<String>,
    pub year: Option<i32>,
    pub serial: Option<String>,
    /// Lower-case 8 hex digits.
    pub crc: Option<String>,
}

/// Entries of `database` ("Sony - PlayStation") with this CRC.
pub fn by_crc(database: &str, crc: u32) -> Vec<DatEntry> {
    let Some(db) = load(database) else { return vec![] };
    let start = db.crc_idx.partition_point(|&(c, _)| c < crc);
    db.crc_idx[start..].iter().take_while(|&&(c, _)| c == crc).map(|&(_, r)| db.entry(r)).collect()
}

/// Entries of `database` with this serial. Dashes, spaces, slashes and case are ignored
/// ("SLUS-20946" = "slus20946"). When nothing matches exactly, serials that start with it are
/// returned (`SLUS-20946GH`, `SLPM-65002-0`, `SLES-55345/ANZ`, GameCube `DL-DOL-GM8E-USA` for
/// "DL-DOL-GM8E", Wii `RMCE01` for "RMCE").
pub fn by_serial(database: &str, serial: &str) -> Vec<DatEntry> {
    let key = norm_serial(serial);
    if key.len() < 3 {
        return vec![];
    }
    let Some(db) = load(database) else { return vec![] };
    let idx = &db.serial_idx;
    let start = idx.partition_point(|(s, _)| s.as_ref() < key.as_str());
    let exact: Vec<DatEntry> =
        idx[start..].iter().take_while(|(s, _)| s.as_ref() == key).map(|&(_, r)| db.entry(r)).collect();
    if !exact.is_empty() || key.len() < 4 {
        return exact;
    }
    idx[start..].iter().take_while(|(s, _)| s.starts_with(key.as_str())).map(|&(_, r)| db.entry(r)).collect()
}

/// Entries of `database` whose ROM file name is `file_name` (case-insensitive).
pub fn by_rom_name(database: &str, file_name: &str) -> Vec<DatEntry> {
    let key = file_name.trim().to_lowercase();
    if key.is_empty() {
        return vec![];
    }
    let Some(db) = load(database) else { return vec![] };
    db.rom_idx.get(&key).map(|rows| rows.iter().map(|&r| db.entry(r)).collect()).unwrap_or_default()
}

/// Names of every embedded database.
#[cfg(test)]
pub fn databases() -> Vec<&'static str> {
    directory().iter().map(|d| d.name).collect()
}

/// Upper-case letters and digits only.
pub fn norm_serial(s: &str) -> String {
    s.chars().filter(|c| c.is_ascii_alphanumeric()).map(|c| c.to_ascii_uppercase()).collect()
}

// ---------------------------------------------------------------------------------------------

struct DirEntry {
    name: &'static str,
    offset: usize,
    clen: usize,
    rlen: usize,
    rows: usize,
}

fn directory() -> &'static [DirEntry] {
    static DIR: OnceLock<Vec<DirEntry>> = OnceLock::new();
    DIR.get_or_init(|| parse_directory(BLOB).unwrap_or_default())
}

fn parse_directory(b: &'static [u8]) -> Option<Vec<DirEntry>> {
    let u32_at = |p: usize| -> Option<usize> { Some(u32::from_le_bytes(b.get(p..p + 4)?.try_into().ok()?) as usize) };
    if b.get(..8)? != b"LSROMDB1" {
        return None;
    }
    let count = u32_at(8)?;
    let mut pos = 12;
    let mut out = Vec::with_capacity(count);
    for _ in 0..count {
        let len = u16::from_le_bytes(b.get(pos..pos + 2)?.try_into().ok()?) as usize;
        let name = std::str::from_utf8(b.get(pos + 2..pos + 2 + len)?).ok()?;
        pos += 2 + len;
        let e = DirEntry {
            name,
            offset: u32_at(pos)?,
            clen: u32_at(pos + 4)?,
            rlen: u32_at(pos + 8)?,
            rows: u32_at(pos + 12)?,
        };
        pos += 16;
        b.get(e.offset..e.offset + e.clen)?;
        out.push(e);
    }
    Some(out)
}

type Span = (u32, u32);

struct Row {
    name: Span,
    region: Span,
    year: Option<i32>,
    serial: Span,
    crc: Option<u32>,
}

struct Db {
    text: String,
    rows: Vec<Row>,
    crc_idx: Vec<(u32, u32)>,
    serial_idx: Vec<(Box<str>, u32)>,
    rom_idx: HashMap<String, Vec<u32>>,
}

impl Db {
    fn s(&self, (a, b): Span) -> &str {
        &self.text[a as usize..b as usize]
    }
    fn opt(&self, sp: Span) -> Option<String> {
        let s = self.s(sp);
        (!s.is_empty()).then(|| s.to_string())
    }
    fn entry(&self, r: u32) -> DatEntry {
        let row = &self.rows[r as usize];
        DatEntry {
            name: self.s(row.name).to_string(),
            region: self.opt(row.region),
            year: row.year,
            serial: self.opt(row.serial),
            crc: row.crc.map(|c| format!("{c:08x}")),
        }
    }
}

fn load(database: &str) -> Option<&'static Db> {
    static DBS: OnceLock<Vec<OnceLock<Option<Db>>>> = OnceLock::new();
    let dir = directory();
    let slots = DBS.get_or_init(|| dir.iter().map(|_| OnceLock::new()).collect());
    let i = dir.iter().position(|d| d.name.eq_ignore_ascii_case(database))?;
    slots[i].get_or_init(|| inflate(&dir[i])).as_ref()
}

fn inflate(d: &DirEntry) -> Option<Db> {
    let raw = miniz_oxide::inflate::decompress_to_vec_with_limit(&BLOB[d.offset..d.offset + d.clen], d.rlen).ok()?;
    let n = d.rows;
    let bitmap_len = n.div_ceil(8);
    let text_start = bitmap_len + 4 * n;
    let bin = raw.get(..text_start)?;
    let text = String::from_utf8(raw.get(text_start..)?.to_vec()).ok()?;
    // Column spans (byte offsets into `text`).
    let mut cols: Vec<Vec<Span>> = Vec::with_capacity(5);
    let mut col_start = 0usize;
    for col in text.split('\0') {
        let mut spans = Vec::with_capacity(n + 1);
        let mut p = col_start;
        for v in col.split('\n') {
            spans.push((p as u32, (p + v.len()) as u32));
            p += v.len() + 1;
        }
        cols.push(spans);
        col_start += col.len() + 1;
    }
    if cols.len() != 5 || cols[..4].iter().any(|c| c.len() != n) || cols[4].len() != n + 1 {
        log::warn!("romdb {}: malformed database", d.name);
        return None;
    }
    let sub = |sp: Span| &text[sp.0 as usize..sp.1 as usize];
    let mut rows = Vec::with_capacity(n);
    let mut crc_idx = Vec::new();
    let mut serial_idx = Vec::new();
    let mut rom_idx: HashMap<String, Vec<u32>> = HashMap::with_capacity(n);
    let common = sub(cols[4][0]).to_string();
    for i in 0..n {
        let has_crc = bin[i / 8] & (1 << (i % 8)) != 0;
        // In bounds: `bin` holds the bitmap and 4 bytes per row.
        let b = &bin[bitmap_len + 4 * i..bitmap_len + 4 * i + 4];
        let crc = has_crc.then(|| u32::from_le_bytes([b[0], b[1], b[2], b[3]]));
        let row =
            Row { name: cols[0][i], region: cols[1][i], year: sub(cols[2][i]).parse().ok(), serial: cols[3][i], crc };
        if let Some(c) = crc {
            crc_idx.push((c, i as u32));
        }
        let serial = norm_serial(sub(row.serial));
        if !serial.is_empty() {
            serial_idx.push((serial.into_boxed_str(), i as u32));
        }
        let name = sub(row.name);
        let coded = sub(cols[4][i + 1]);
        let rom = if coded.is_empty() {
            format!("{name}{common}")
        } else if let Some(suffix) = coded.strip_prefix('+') {
            format!("{name}{suffix}")
        } else {
            coded.to_string()
        };
        if !rom.is_empty() {
            rom_idx.entry(rom.to_lowercase()).or_default().push(i as u32);
        }
        rows.push(row);
    }
    crc_idx.sort_unstable();
    serial_idx.sort_unstable();
    Some(Db { text, rows, crc_idx, serial_idx, rom_idx })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_databases_load() {
        let names = databases();
        assert!(names.len() > 100, "{}", names.len());
        assert!(names.contains(&"Sony - PlayStation 2"));
        // Every database inflates and indexes.
        for n in &names {
            assert!(load(n).is_some(), "{n}");
        }
        assert!(load("No Such Console").is_none());
        assert!(by_crc("No Such Console", 1).is_empty());
    }

    #[test]
    fn lookups_by_crc_serial_and_rom_name() {
        // Ocarina of Time (USA) z64 (from the research notes, verified on a real dump).
        let hits = by_crc("Nintendo - Nintendo 64", 0xcd16c529);
        assert!(hits.iter().any(|e| e.name.starts_with("Legend of Zelda, The - Ocarina of Time (USA)")), "{hits:?}");
        assert!(hits.iter().all(|e| e.crc.as_deref() == Some("cd16c529")));
        // PS2 serial, any dash / case spelling.
        let a = by_serial("Sony - PlayStation 2", "SLUS-20238");
        assert!(a.iter().any(|e| e.name.contains("Wrath of Cortex")), "{a:?}");
        assert_eq!(a, by_serial("sony - playstation 2", "slus20238"));
        // Prefix fallback: GameCube Redump rows by the disc id.
        let gc = by_serial("Nintendo - GameCube", "DL-DOL-GXXE");
        assert!(gc.iter().any(|e| e.serial.as_deref() == Some("DL-DOL-GXXE-USA")), "{gc:?}");
        let gc6 = by_serial("Nintendo - GameCube", "GXXE01");
        assert!(gc6.iter().any(|e| e.name == "Pokémon XD: Gale of Darkness (USA)"), "{gc6:?}");
        assert_eq!(gc6[0].year, Some(2005));
        // Too short / unknown.
        assert!(by_serial("Sony - PlayStation 2", "S-").is_empty());
        assert!(by_serial("Sony - PlayStation 2", "ZZZZ-99999").is_empty());
        // Rom names (case-insensitive), common suffix and "(Track 1).bin" style.
        let nds = by_rom_name("Nintendo - Nintendo DS", "pokemon - black version (usa, europe) (ndsi enhanced).NDS");
        assert!(nds.iter().any(|e| e.serial.as_deref() == Some("IRBO")), "{nds:?}");
        let ps1 = by_rom_name("Sony - PlayStation", "Dragstars (Europe) (Track 1).bin");
        assert_eq!(ps1.first().map(|e| e.serial.as_deref()), Some(Some("SLES-03525")));
        assert_eq!(ps1[0].region.as_deref(), Some("Europe"));
    }
}
